-- New catalog entries only; safe to rerun without overwriting CMS edits.
BEGIN;
-- Standardize reviewed existing quote products while preserving their approved price text.
UPDATE public.products SET external_link_config = COALESCE(external_link_config, '{}'::jsonb) || jsonb_build_object('buttonText','Line 報價預約','url','https://line.me/R/ti/p/@021souxl')
WHERE id IN ('accessible-space','bathroom-renovation','decor-design','elderly-housing-exchange','health-fitness','home-inspection','light-renovation','old-house-diagnosis','real-estate','rental-customization','rental-management','safe-moving','safety-assessment','short-term-care') AND order_mode = 'EXTERNAL_LINK';
UPDATE public.products SET order_mode = 'EXTERNAL_LINK', external_link_config = COALESCE(external_link_config, '{}'::jsonb) || jsonb_build_object('priceText',COALESCE(internal_form_config->>'priceText','依需求報價'),'buttonText','Line 報價預約','url','https://line.me/R/ti/p/@021souxl')
WHERE id = 'home-reorganization' AND order_mode = 'INTERNAL_FORM';
COMMIT;
